import re
import numpy as np

# The sandbox has no network, so embed() stands in for an embeddings API (OpenAIEmbeddings)
# and a numpy matrix plays the role of the FAISS index. embed() returns unit-length
# vectors, so a dot product is the cosine similarity.
TOPIC_WORDS = {
    0: {"created", "creator", "guido", "rossum", "who", "invented", "made", "create"},
    1: {"released", "release", "2008", "version", "when", "year"},
    2: {"zen", "principles", "guiding", "philosophy", "aphorisms"},
    3: {"pip", "install", "installs", "packages", "package", "index", "library", "libraries"},
    4: {"indentation", "blocks", "block", "whitespace", "spaces", "indent"},
}


def embed(text):
    vec = np.full(6, 0.01)
    for word in re.findall(r"[a-z0-9]+", text.lower()):
        for dim, words in TOPIC_WORDS.items():
            if word in words:
                vec[dim] += 1.0
                break
        else:
            vec[5] += 0.1
    return vec / np.linalg.norm(vec)


facts = [
    "Python was created by Guido van Rossum.",
    "Python 3.0 was released in 2008.",
    "The Zen of Python lists 19 guiding principles.",
    "pip installs packages from the Python Package Index.",
    "Python uses indentation to define code blocks.",
]


def build_index(facts):
    """Return a 2D numpy array: one embedding per fact (like FAISS.from_texts)."""
    return np.array([embed(f) for f in facts])


def search(index, question, k=2):
    """Return the row indexes of the k facts most similar to the question, best first."""
    scores = index @ embed(question)
    return [int(i) for i in np.argsort(-scores)[:k]]


def ask(question, facts, index, k=2):
    """Retrieve the relevant facts and format them as context for an LLM prompt."""
    context = "\n".join("- " + facts[i] for i in search(index, question, k))
    return f"Context:\n{context}\n\nQuestion: {question}"


index = build_index(facts)
print(ask("Who created Python?", facts, index))
